// The Algorithms page's knowledge-graph hydrate (#2856) — the live read over the packaged seed.
// `loadGraph` returns `null` when the read is unavailable (the web shell, the tests) so the page keeps
// rendering the embedded seed rather than blanking. The whole-graph doc is shape-gated
// (`implementations` must be an array) before it's trusted, matching themeBridge's discipline.
//
// IN-PROCESS since #4078 (`graph_dump`), not the `bsc` bridge. `useKnowledgeGraph` polls this every 5s
// while the page is mounted, and through the bridge every tick SPAWNED a subprocess — to read 84 KB,
// hash it, and discard the result because nothing had changed, which is the common case. The command
// calls `bsc_graph::load`, the CLI's own reader, so it resolves the same store and reconciles the same
// seed; the rows are byte-identical.
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { buildKnowledge, type AlgoImpl, type KnowledgeGraph, type RawKnowledge } from "@/features/algorithms/lib/knowledge";

/** Read the librarian's writable store (`~/.base-studio-code/knowledge/algorithms.json`, #2853) and
 *  build the {@link KnowledgeGraph}. `null` on ANY failure — an unavailable command, or a payload whose
 *  `implementations` isn't an array — so a degraded environment simply shows the packaged seed. */
export async function loadGraph(): Promise<KnowledgeGraph | null> {
  try {
    const doc = await safeInvoke<{ implementations?: unknown } | null>(
      "graph_dump",
      undefined,
      null,
    );
    if (!doc || !Array.isArray(doc.implementations)) return null;
    return buildKnowledge(doc as unknown as RawKnowledge);
  } catch {
    return null;
  }
}

/** The store's content signature, or `null` when it cannot be read.
 *
 *  THE POLL'S CHEAP FIRST QUESTION. `loadGraph` transfers the whole projected document; this transfers
 *  64 characters, and the answer to "has anything changed" is no on the overwhelming majority of ticks
 *  — which is what makes a 5-second poll over a growing store affordable at all.
 *
 *  `null` means CANNOT TELL, never "unchanged": a caller must fall through to a full read on it, or an
 *  error would silently freeze the page on whatever it last rendered. */
export async function loadGraphSig(): Promise<string | null> {
  try {
    const sig = await safeInvoke<string | null>("graph_sig", undefined, null);
    return typeof sig === "string" && sig.length > 0 ? sig : null;
  } catch {
    return null;
  }
}
/** ONE record's source (`code`, `vizCode`) by id, or `null`.
 *
 *  Bodies are NOT in the hydrate. `graph_dump` ships the index the graph renders — 0.93 MB — and the
 *  inspector asks for the selected record's source when it needs it. Shipping all 1,401 bodies to show
 *  one is what made the poll unaffordable: they were 19.31 MB of a 20.26 MB payload. */
export async function loadImplSource(id: string): Promise<{ code?: string; vizCode?: string } | null> {
  try {
    const rec = await safeInvoke<{ code?: string | null; vizCode?: string | null } | null>(
      "graph_impl_source",
      { id },
      null,
    );
    if (!rec) return null;
    return { code: rec.code ?? undefined, vizCode: rec.vizCode ?? undefined };
  } catch {
    return null;
  }
}
/** Every record that PROVIDES a specifier, with its source — what `resolveGraphSource` matches against.
 *
 *  A DIFFERENT READ FROM `loadGraph`, and keeping them apart is the whole point. `loadGraph` returns the
 *  page's INDEX, which carries no bodies; the resolver turns a graph module's `@/…` import into source
 *  and therefore needs exactly the bodies the index drops. While both went through `graph_dump`,
 *  shrinking the page's payload silently stopped every record-provided module in the app from
 *  resolving — including the ones the Algorithms page is itself built from.
 *
 *  661 records of 1,402 provide something, so this is 4.32 MB, and it is read ONCE at boot, not polled. */
export async function loadModules(): Promise<{ implementations: AlgoImpl[] } | null> {
  try {
    const doc = await safeInvoke<{ implementations?: unknown } | null>("graph_modules", undefined, null);
    if (!doc || !Array.isArray(doc.implementations)) return null;
    return { implementations: doc.implementations as AlgoImpl[] };
  } catch {
    return null;
  }
}

